import org.jsoup.nodes.Document;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextNodeTest {
	@Test
	public void nodeNameTest() {
		TextNode node = new TextNode("Test");
		assertEquals("Text Node Name mismatch", "#text", node.nodeName());
	}

	@Test
	public void textTest() {
		TextNode node = new TextNode("Test");
		assertEquals("Text Node Text mismatch", "Test", node.text());
	}

	@Test
	public void textSetterTest() {
		TextNode node = new TextNode("Test");
		node.text("New Test");
		assertEquals("Text Node Text mismatch after set", "New Test", node.text());
	}

	@Test
	public void getWholeTextTest() {
		TextNode node = new TextNode("Test");
		assertEquals("Whole Text Node Text mismatch", "Test", node.getWholeText());
	}

	@Test
	public void isBlankTest() {
		TextNode node = new TextNode("");
		assertTrue("Blank Text Node is not identified as Blank", node.isBlank());
	}

	@Test
	public void isNotBlankTest() {
		TextNode node = new TextNode("Not Blank");
		assertFalse("Non Blank Text Node is identified as Blank", node.isBlank());
	}

	@Test
	public void splitTextTest() {
		TextNode node = new TextNode("Hello World");
		TextNode newTextNode = node.splitText(5);
		assertEquals("Split Text failed", "Hello", node.text());
		assertEquals("New Text Node after split wrong text", "World", newTextNode.text());
	}

	@Test
	public void outerHtmlHeadTest() throws IOException {
		TextNode node = new TextNode("Test");
		StringBuilder accum = new StringBuilder();
		node.outerHtmlHead(accum, 0, new Document.OutputSettings());
		assertEquals("OuterHtmlHead output mismatch", "Test", accum.toString());
	}

	@Test
	public void outerHtmlTailTest() throws IOException {
		TextNode node = new TextNode("Test");
		StringBuilder accum = new StringBuilder();
		node.outerHtmlTail(accum, 0, new Document.OutputSettings());
		assertEquals("OuterHtmlTail output mismatch", "", accum.toString());
	}

	@Test
	public void cloneTest() {
		TextNode node = new TextNode("Test");
		TextNode clone = node.clone();
		assertNotSame("Clone Test Node is same object", node, clone);
		assertEquals("Clone Test Node has different text", node.getWholeText(), clone.getWholeText());
	}

	@Test
	public void createFromEncodedTest() {
		TextNode node = TextNode.createFromEncoded("Test");
		assertEquals("Created from Encoded Text Node text mismatch", "Test", node.getWholeText());
	}

	@Test
	public void normaliseWhitespaceTest() {
		String result = TextNode.normaliseWhitespace(" Test  ");
		assertEquals("Whitespace Normalization failed", " Test ", result);
	}

	@Test
	public void stripLeadingWhitespaceTest() {
		String result = TextNode.stripLeadingWhitespace(" Test");
		assertEquals("Strip Leading Whitespace failed", "Test", result);
	}

	@Test
	public void lastCharIsWhitespaceTest() {
		boolean result = TextNode.lastCharIsWhitespace(new StringBuilder("Test "));
		assertTrue("Last Character is not identified as Whitespace", result);
	}

	@Test
	public void lastCharIsNotWhitespaceTest() {
		boolean result = TextNode.lastCharIsWhitespace(new StringBuilder("Test"));
		assertFalse("Non Whitespace Last Character identified as Whitespace", result);
	}
}
